mapper.select:
SELECT d.diary_id, d.worked_at, c.crop_name, c.variety_name, p.plan_name, g.greenhouse_name, d.growth_stage, (SELECT COUNT(*) FROM cultivation_diary_task t WHERE t.diary_id = d.diary_id AND t.deleted_at IS NULL) AS task_count, (SELECT COUNT(*) FROM cultivation_diary_task t WHERE t.diary_id = d.diary_id AND t.deleted_at IS NULL AND t.task_status = '미완료') AS incomplete_task_count FROM cultivation_diary AS d JOIN cultivation_plan AS p ON p.plan_id = d.plan_id JOIN greenhouse AS g ON g.greenhouse_id = p.greenhouse_id JOIN crop_stage_standard AS s ON s.standard_id = p.standard_id JOIN crop AS c ON c.crop_id = s.crop_id WHERE p.member_id = #{memberId} AND d.deleted_at IS NULL AND p.deleted_at IS NULL AND g.deleted_at IS NULL
AND p.plan_name = #{planName}
AND c.crop_name = #{cropName}
AND c.variety_name = #{varietyName}
AND d.worked_at >= #{workedDate} AND d.worked_at < DATE_ADD(#{workedDate}, INTERVAL 1 DAY)
AND g.greenhouse_name = #{greenhouseName}
ORDER BY d.worked_at DESC, d.diary_id DESC

SELECT DISTINCT crop_name
FROM crop
ORDER BY crop_name;

SELECT DISTINCT c.variety_name FROM crop AS c
c.crop_name = #{cropName}
ORDER BY c.variety_name

SELECT d.growth_stage
FROM cultivation_diary AS d
JOIN cultivation_plan AS p ON p.plan_id = d.plan_id
WHERE d.plan_id = #{planId}
AND p.member_id = #{memberId}
AND d.worked_at < #{workedDate}
AND d.deleted_at IS NULL
AND p.deleted_at IS NULL
ORDER BY d.worked_at DESC, d.diary_id DESC
LIMIT 1

mapper.insert:
INSERT INTO cultivation_diary (
plan_id, worked_at, growth_stage, stage_change_reason, created_at
)
SELECT p.plan_id, #{diary.workedAt}, #{diary.growthStage},
#{diary.stageChangeReason}, CURRENT_TIMESTAMP
FROM cultivation_plan AS p
WHERE p.plan_id = #{diary.planId}
AND p.member_id = #{memberId}
AND p.deleted_at IS NULL

mapper.update:
UPDATE cultivation_diary AS d
JOIN cultivation_plan AS p ON p.plan_id = d.plan_id
SET d.deleted_at = CURRENT_TIMESTAMP
WHERE d.diary_id = #{diaryId}
AND p.member_id = #{memberId}
AND d.deleted_at IS NULL

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM cultivation_diary
    WHERE plan_id = #{planId} AND deleted_at IS NULL
      AND worked_at >= #{workedDate}
      AND worked_at < DATE_ADD(#{workedDate}, INTERVAL 1 DAY)
)
